const xml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const fmt=(n,d=2)=>Number.isFinite(n)?n.toFixed(d):'Unavailable';
const point=(r,degree,cx=360,cy=360)=>{const a=(degree-90)*Math.PI/180;return[cx+r*Math.cos(a),cy+r*Math.sin(a)];};
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=String(text);if(cls)n.className=cls;return n;};
const show=value=>typeof value==='string'?value:JSON.stringify(value);
function sourceLink(source){const p=el('p',null,'sky-source');p.append(el('strong',source.title||source.label||source.id));if(source.locator)p.append(document.createTextNode(` · ${source.locator}`));try{const u=new URL(source.url,SITE_ROOT);if(['http:','https:'].includes(u.protocol)){const a=el('a','Read source ↗');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';p.append(document.createTextNode(' · '),a);}}catch{}return p;}
function arcPath(r,start,end){const a=point(r,start),b=point(r,end);return`M ${a[0]} ${a[1]} A ${r} ${r} 0 ${end-start>180?1:0} 1 ${b[0]} ${b[1]}`;}
function dateInput(iso){return iso.slice(0,10);}

