  let active=true,current=null,snapshot=null,reading=null,alignment=null,alignmentOptions=null,alignmentDirty=false,mode='zodiac',selectedBody='Moon',selectedLenses=['lilly','agrippa','jyotisha'],overlay=false,ringsHidden=new Set(),timeline=null,worker=null,job=0,busy=false,ics=null,svg='',ruleNavigator=null,timelineNavigator=null;
