  const fail=message=>{$('sky-error').textContent=message||'';$('sky-error').hidden=!message;};
  function setControls(){const disabled=!active||!current;ruleNavigator?.update({disabled});timelineNavigator?.update({disabled:disabled||busy||!timeline});for(const id of ['sky-view-zodiac','sky-view-simple','sky-view-orbit','sky-overlay','sky-body','sky-stars','sky-catalog-stars','sky-aspects','sky-yaw','sky-tilt','sky-scale'])$(id).disabled=disabled;for(const box of $('sky-lenses').querySelectorAll('input'))box.disabled=disabled;for(const id of ['sky-svg','sky-reading-json','sky-build-timeline','sky-alignment-apply','sky-ics-preview'])$(id).disabled=disabled||(id==='sky-build-timeline'&&busy)||(id==='sky-reading-json'&&alignmentDirty);$('sky-cancel-timeline').disabled=!busy;for(const id of ['sky-sample-prev','sky-sample-next','sky-sample-cast','sky-time-range','sky-timeline-json'])$(id).disabled=disabled||!timeline||busy;$('sky-ics-download').disabled=disabled||!ics;}
  function clearICS() {ics=null;$('sky-ics-download').disabled=true;$('sky-ics-content').hidden=true;$('sky-ics-content').textContent='';$('sky-ics-disclosure').textContent='';}
