  function renderChart(){if(!snapshot||!current)return;svg=mode==='orbit'?orbitSVG():zodiacSVG();$('sky-chart').innerHTML=svg;$('sky-chart-caption').textContent=mode==='orbit'?'Three-dimensional positions projected onto the page. Grid circles mark distance in the ecliptic plane, not calculated orbits. Rotate with the labelled controls; the geocentric interpretation remains separate.':'Planets: apparent geocentric longitudes. Catalogue stars: geometric propagated directions; historical markers: approximate longitudes. Zero Aries is at top, increasing clockwise. Radial lanes separate symbols, not distances. Select a mark or use the menu.';$('sky-orbit-controls').hidden=mode!=='orbit';$('sky-stars').closest('label').hidden=mode==='orbit';$('sky-catalog-stars').closest('label').hidden=mode==='orbit';$('sky-aspects').closest('label').hidden=mode==='orbit';$('sky-catalogue-credit').replaceChildren();if(mode!=='orbit'&&$('sky-catalog-stars').checked&&snapshot.catalogue){const credit=snapshot.catalogue;$('sky-catalogue-credit').append(document.createTextNode(`Catalogue: ${credit.label||credit.title||'HYG selected-star data'} · ${credit.license||'see source licence'} · `));try{const u=new URL(credit.sourceURL);if(['http:','https:'].includes(u.protocol)){const a=el('a','Source & attribution');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';$('sky-catalogue-credit').append(a);}}catch{}}for(const node of $('sky-chart').querySelectorAll('[data-sky-body]')){const choose=()=>selectBody(node.dataset.skyBody);node.addEventListener('click',choose);node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const id=node.dataset.skyBody;choose();[...$('sky-chart').querySelectorAll('[data-sky-body]')].find(n=>n.dataset.skyBody===id)?.focus();}});}}
