    const focus=mark=>{for(const node of marks)node.setAttribute('tabindex',node===mark?'0':'-1');};
    for(const mark of marks){const show=pin=>{const event=timeline.events[Number(mark.dataset.eventIndex)];timelineNavigator?.preview('event@'+(event.dateISO||event.instantUTC),{anchor:mark,pin});};mark.addEventListener('pointerenter',()=>show(false));mark.addEventListener('focus',()=>{focus(mark);show(false);});mark.addEventListener('click',()=>{focus(mark);show(true);});mark.addEventListener('keydown',event=>{const index=marks.indexOf(mark);if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?marks.length-1:Math.max(0,Math.min(marks.length-1,index+(event.key==='ArrowRight'?1:-1)));focus(marks[next]);marks[next].focus();}else if(['Enter',' '].includes(event.key)){event.preventDefault();show(true);}});}
